import { getDb } from './database';

interface SeedQuestion {
  question: string;
  a: string;
  b: string;
  c: string;
  d: string;
  correct: 'a' | 'b' | 'c' | 'd';
  explanation: string;
}

interface SeedPage {
  title: string;
  body: string;
  questions: SeedQuestion[];
  // Curriculum position within the domain, not array position — lets pages be
  // appended to the array in any order (e.g. whenever a new topic is written)
  // while still displaying in true page-1-to-end textbook sequence. Spaced by
  // 10s so earlier chapters can be inserted later without renumbering
  // everything already shipped.
  order: number;
}

interface SeedDomain {
  slug: string;
  name: string;
  color: string;
  pages: SeedPage[];
}

