export async function seedIfEmpty(): Promise<void> {
  const db = await getDb();
  const countRow = await db.getFirstAsync<{ c: number }>('SELECT COUNT(*) as c FROM domains');
  if ((countRow?.c ?? 0) > 0) return;

  await db.withTransactionAsync(async () => {
    for (let di = 0; di < SEED_DOMAINS.length; di++) {
      const domain = SEED_DOMAINS[di];
      const domainResult = await db.runAsync(
        'INSERT INTO domains (slug, name, color, sort_order) VALUES (?, ?, ?, ?)',
        [domain.slug, domain.name, domain.color, di]
      );
      const domainId = domainResult.lastInsertRowId;

      // Insert in curriculum order (the `order` field), not array order —
      // pages can be appended to the source array in any sequence.
      const orderedPages = [...domain.pages].sort((a, b) => a.order - b.order);

      for (let pi = 0; pi < orderedPages.length; pi++) {
        const page = orderedPages[pi];
        const pageResult = await db.runAsync(
          'INSERT INTO pages (domain_id, title, body, sort_order) VALUES (?, ?, ?, ?)',
          [domainId, page.title, page.body, page.order]
        );
        const pageId = pageResult.lastInsertRowId;

        for (let qi = 0; qi < page.questions.length; qi++) {
          const q = page.questions[qi];
          await db.runAsync(
            `INSERT INTO questions
              (page_id, question, choice_a, choice_b, choice_c, choice_d, correct_choice, explanation, sort_order)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [pageId, q.question, q.a, q.b, q.c, q.d, q.correct, q.explanation, qi]
          );
        }
      }
    }
  });
}
